export function normalizeLoaiPTTT(raw?: string | null): string {
  if (!raw) return '';
  const s = String(raw).trim().toUpperCase();
  if (s === 'PDB' || s === 'PĐB') return 'PĐB';
  if (s === 'TDB' || s === 'TĐB') return 'TĐB';
  if (['P1', 'P2', 'P3', 'T1', 'T2', 'T3', 'TKPL'].includes(s)) return s;
  return '';
}

export function resolveDefaultLoaiPTTT(
  tenKT?: string | null,
  maTuongDuong?: string | null,
  explicitLoai?: string | null
): string {
  const explicit = normalizeLoaiPTTT(explicitLoai);
  if (explicit) return explicit;

  if (maTuongDuong) {
    const mtd = String(maTuongDuong).trim();
    if (DEFAULT_LOAI_BY_MTD[mtd]) return DEFAULT_LOAI_BY_MTD[mtd];
    const baseMtd = mtd.replace(/_GT$/i, '');
    if (DEFAULT_LOAI_BY_MTD[baseMtd]) return DEFAULT_LOAI_BY_MTD[baseMtd];
  }

  if (tenKT) {
    const cleanName = String(tenKT).trim().toLowerCase().replace(/\s+/g, ' ');
    if (DEFAULT_LOAI_BY_NAME[cleanName]) return DEFAULT_LOAI_BY_NAME[cleanName];
    const withoutGayTe = cleanName.replace(/\s*\[(gây tê|gây mê)\]\s*/g, '').trim();
    if (DEFAULT_LOAI_BY_NAME[withoutGayTe]) return DEFAULT_LOAI_BY_NAME[withoutGayTe];
  }

  return '';
}
